import{_ as a,o,c as d,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const R=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/REREAD.md","filePath":"manual-zh/REREAD.md","lastUpdated":1785684581000}'),r={name:"manual-zh/REREAD.md"};function t(n,e,E,s,p,l){return o(),d("div",null,[...e[0]||(e[0]=[c(`<h3 id="_8-15-reread" tabindex="-1">8.15 REREAD <a class="header-anchor" href="#_8-15-reread" aria-label="Permalink to &quot;8.15 REREAD&quot;">​</a></h3><pre><code>REREAD [FILE=handle] [COLUMN=column] [ENCODING=’encoding’].
</code></pre><p><code>REREAD</code> 转换允许将由 <code>DATA LIST</code> 或其他输入命令已处理过的数据文件中先前的输入行重新读取，以便进一步处理。</p><p>可选的 <code>FILE</code> 子命令用于指定要重新读取其行的文件。该文件必须以文件句柄名称的形式给出（参见 <a href="./File-Handles">File Handles</a>）。如果未指定 FILE，则假定为 <code>DATA LIST</code> 上最后指定的文件（按词法顺序最后指定的文件，而非控制流顺序）。</p><p>默认情况下，被重新读取的行将被整行重新读取。通过 <code>COLUMN</code> 子命令，可以使该行的某个前缀免于被重新读取。指定一个表达式（参见 <a href="./Expressions">Expressions</a>），其求值结果为应包含在重新读取行中的起始列。列从左侧边界的第 1 列开始编号。</p><p><code>ENCODING</code> 子命令只有在同时使用了 <code>FILE</code> 子命令时才能使用。它指定文件的字符编码。有关受支持编码的信息，请参见 <a href="./INSERT">INSERT</a>。</p><p>多次发出 <code>REREAD</code> 不会在文件中向后回退，而是会将同一行重新读取多次。</p>`,7)])])}const i=a(r,[["render",t]]);export{R as __pageData,i as default};
